const DICTS = { pt, en, es, fr };
let current = 'pt';

export function setLang(lang) { current = DICTS[lang] ? lang : 'pt'; return current; }
export const getLang = () => current;
export const locale = () => LOCALES[current];

// Sugere a língua do browser na primeira vez
export function guessLang() {
  const nav = (globalThis.navigator?.languages ?? [globalThis.navigator?.language ?? 'pt']).map(l => String(l).slice(0, 2));
  return nav.find(l => DICTS[l]) ?? 'pt';
}

export function t(key, params) {
  let s = DICTS[current][key] ?? pt[key] ?? key;
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] ?? m));
  return s;
}

// Traduz o HTML: data-i18n (texto), data-i18n-ph (placeholder), data-i18n-title, data-i18n-aria
export function translateDom(root = document) {
  root.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-ph]').forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll('[data-i18n-title]').forEach(el => { el.title = t(el.dataset.i18nTitle); });
  root.querySelectorAll('[data-i18n-aria]').forEach(el => { el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
  document.documentElement.lang = LOCALES[current];
}

// Para testes: chaves que faltam em cada língua
export function missingKeys() {
  const out = {};
  for (const [l, d] of Object.entries(DICTS)) out[l] = Object.keys(pt).filter(k => !(k in d));
  return out;
}
